{"command":"cat <<'EOF' > elfcat.py
import sys
import os
import struct
import html

def format_size(size):
    if size < 1024:
        return f"{size} B"
    return f"{size / 1024:.1f} KiB ({size} B)"

def get_elf_info(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    file_size = len(data)
    if file_size < 52:
        return None

    ei_class = data[4]
    is_64 = ei_class == 2
    ei_data = data[5]
    is_le = ei_data == 1
    endian = '<' if is_le else '>'

    if is_64:
        ehdr_fmt = endian + '16sHHIQQQIHHHHHH'
        ehdr_size = 64
    else:
        ehdr_fmt = endian + '16sHHIIIIIHHHHHH'
        ehdr_size = 52

    if len(data) < ehdr_size: return None
    ehdr_data = struct.unpack(ehdr_fmt, data[:ehdr_size])

    # ... (collecting ehdr fields)
    e_info = {
        'e_ident': ehdr_data[0],
        'e_type': ehdr_data[1],
        'e_machine': ehdr_data[2],
        'e_version': ehdr_data[3],
        'e_entry': ehdr_data[4],
        'e_phoff': ehdr_data[5],
        'e_shoff': ehdr_data[6],
        'e_flags': ehdr_data[7],
        'e_ehsize': ehdr_data[8],
        'e_phentsize': ehdr_data[9],
        'e_phnum': ehdr_data[10],
        'e_shentsize': ehdr_data[11],
        'e_shnum': ehdr_data[12],
        'e_shstrndx': ehdr_data[13],
    }

    # Phdr table
    phdrs = []
    if e_info['e_phoff'] != 0:
        for i in range(e_info['e_phnum']):
            off = e_info['e_phoff'] + i * e_info['e_phentsize']
            if is_64:
                phdr_fmt = endian + 'IIQQQQQQ'
                p_data = struct.unpack(phdr_fmt, data[off:off+56])
                phdrs.append({'index': i, 'type': p_data[0], 'flags': p_data[1], 'offset': p_data[2], 'vaddr': p_data[3], 'paddr': p_data[4], 'filesz': p_data[5], 'memsz': p_data[6], 'align': p_data[7]})
            else:
                phdr_fmt = endian + 'IIIIIIII'
                p_data = struct.unpack(phdr_fmt, data[off:off+32])
                phdrs.append({'index': i, 'type': p_data[0], 'offset': p_data[1], 'vaddr': p_data[2], 'paddr': p_data[3], 'filesz': p_data[4], 'memsz': p_data[5], 'flags': p_data[6], 'align': p_data[7]})

    # Shdr table
    shdrs = []
    if e_info['e_shoff'] != 0:
        for i in range(e_info['e_shnum']):
            off = e_info['e_shoff'] + i * e_info['e_shentsize']
            if is_64:
                shdr_fmt = endian + 'IIQQQQIIQQ'
                s_data = struct.unpack(shdr_fmt, data[off:off+64])
                shdrs.append({'index': i, 'name_off': s_data[0], 'type': s_data[1], 'flags': s_data[2], 'addr': s_data[3], 'offset': s_data[4], 'size': s_data[5], 'link': s_data[6], 'info': s_data[7], 'addralign': s_data[8], 'entsize': s_data[9]})
            else:
                shdr_fmt = endian + 'IIIIIIIIII'
                s_data = struct.unpack(shdr_fmt, data[off:off+40])
                shdrs.append({'index': i, 'name_off': s_data[0], 'type': s_data[1], 'flags': s_data[2], 'addr': s_data[3], 'offset': s_data[4], 'size': s_data[5], 'link': s_data[6], 'info': s_data[7], 'addralign': s_data[8], 'entsize': s_data[9]})

    if e_info['e_shstrndx'] < len(shdrs):
        shstr_off = shdrs[e_info['e_shstrndx']]['offset']
        for s in shdrs:
            name_off = s['name_off']
            name = ""
            while shstr_off + name_off < len(data) and data[shstr_off + name_off] != 0:
                name += chr(data[shstr_off + name_off])
                name_off += 1
            s['name'] = name
    else:
        for s in shdrs: s['name'] = ""

    return {
        'data': data,
        'filename': os.path.basename(filename),
        'file_size': file_size,
        'is_64': is_64,
        'is_le': is_le,
        'e_info': e_info,
        'phdrs': phdrs,
        'shdrs': shdrs,
    }

def get_type_str(t):
    return {0: 'NONE (None)', 1: 'Relocatable file (REL)', 2: 'Executable file (EXEC)', 3: 'Shared object file (DYN)', 4: 'Core file (CORE)'}.get(t, f"Unknown ({t})")

def get_machine_str(m):
    return {0: 'None', 3: 'x86', 40: 'ARM', 62: 'x86-64', 183: 'AArch64'}.get(m, f"Unknown ({m})")

def get_abi_str(a):
    return {0: 'SysV', 1: 'HP-UX', 2: 'NetBSD', 3: 'Linux', 6: 'Solaris', 7: 'AIX', 8: 'IRIX', 9: 'FreeBSD', 10: 'Tru64', 11: 'Novell Modesto', 12: 'OpenBSD'}.get(a, f"Unknown ({a})")

def get_phdr_type(t):
    return {0: 'NULL', 1: 'LOAD', 2: 'DYNAMIC', 3: 'INTERP', 4: 'NOTE', 5: 'SHLIB', 6: 'PHDR', 7: 'TLS', 0x6474e550: 'GNU_EH_FRAME', 0x6474e551: 'GNU_STACK', 0x6474e552: 'GNU_RELRO'}.get(t, f"Unknown ({hex(t)})")

def get_shdr_type(t):
    if t >= 0x60000000:
        types = {0x6ffffff6: 'GNU_HASH (OS-specific)', 0x6fffffff: 'VERNEED (OS-specific)', 0x6ffffffe: 'VERDEF (OS-specific)', 0x6fffffff: 'VERSYM (OS-specific)'}
        return types.get(t, f"Unknown ({hex(t)})")
    return {0: 'NULL', 1: 'PROGBITS', 2: 'SYMTAB', 3: 'STRTAB', 4: 'RELA', 5: 'HASH', 6: 'DYNAMIC', 7: 'NOTE', 8: 'NOBITS', 9: 'REL', 10: 'SHLIB', 11: 'DYNSYM'}.get(t, f"Unknown ({t})")

def p_flags_str(flags):
    s = ""
    if flags & 4: s += 'R'
    if flags & 2: s += 'W'
    if flags & 1: s += 'X'
    return s if s else '0'

def sh_flags_str(flags):
    s = ""
    if flags & 0x1: s += 'W'
    if flags & 0x2: s += 'A'
    if flags & 0x4: s += 'X'
    if flags & 0x10: s += 'M'
    if flags & 0x20: s += 'S'
    if flags & 0x40: s += 'I'
    if flags & 0x80: s += 'L'
    if flags & 0x100: s += 'O'
    if flags & 0x200: s += 'G'
    if flags & 0x400: s += 'T'
    return s if s else '0'

def generate_html(info):
    # ... (this will be a long one)
    pass

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: elfcat <filename>")
        sys.exit(1)
    info = get_elf_info(sys.argv[1])
    if info:
        # generate_html(info)
        pass
EOF
