def get_machine_str(m):
    return {0: 'None', 3: 'x86', 40: 'ARM', 62: 'x86-64', 183: 'AArch64'}.get(m, f"Unknown ({m})")

def get_abi_str(a):
    return {0: 'SysV', 1: 'HP-UX', 2: 'NetBSD', 3: 'Linux', 6: 'Solaris', 7: 'AIX', 8: 'IRIX', 9: 'FreeBSD', 10: 'Tru64', 11: 'Novell Modesto', 12: 'OpenBSD'}.get(a, f"Unknown ({a})")

def get_phdr_type(t):
    return {0: 'NULL', 1: 'LOAD', 2: 'DYNAMIC', 3: 'INTERP', 4: 'NOTE', 5: 'SHLIB', 6: 'PHDR', 7: 'TLS', 0x6474e550: 'GNU_EH_FRAME', 0x6474e551: 'GNU_STACK', 0x6474e552: 'GNU_RELRO'}.get(t, f"Unknown ({hex(t)})")

def get_shdr_type(t):
    if t >= 0x60000000:
        types = {0x6ffffff6: 'GNU_HASH (OS-specific)', 0x6fffffff: 'VERSYM (OS-specific)', 0x6ffffffe: 'VERDEF (OS-specific)', 0x6fffffff: 'VERNEED (OS-specific)'}
        if t in types: return types[t]
        return f"Unknown ({hex(t)})"
    return {0: 'NULL', 1: 'PROGBITS', 2: 'SYMTAB', 3: 'STRTAB', 4: 'RELA', 5: 'HASH', 6: 'DYNAMIC', 7: 'NOTE', 8: 'NOBITS', 9: 'REL', 10: 'SHLIB', 11: 'DYNSYM'}.get(t, f"Unknown ({t})")

def p_flags_str(flags):
    s = ""
    if flags & 4: s += 'R'
    if flags & 2: s += 'W'
    if flags & 1: s += 'X'
    return s if s else '0'

def sh_flags_str(flags):
    s = ""
    if flags & 0x1: s += 'W'
    if flags & 0x2: s += 'A'
    if flags & 0x4: s += 'X'
    if flags & 0x10: s += 'M'
    if flags & 0x20: s += 'S'
    if flags & 0x40: s += 'I'
    if flags & 0x80: s += 'L'
    if flags & 0x100: s += 'O'
    if flags & 0x200: s += 'G'
    if flags & 0x400: s += 'T'
    return s if s else '0'

def generate_html(info):
    data = info['data']
    is_64 = info['is_64']
    e = info['e_info']

    intervals = []
    intervals.append((0, e['e_ehsize'], 'ehdr', 2))
    intervals.append((0, 16, 'ident', 3))
    intervals.append((0, 4, 'magic', 4))
    intervals.append((4, 5, 'class', 4))
    intervals.append((5, 6, 'data', 4))
    intervals.append((6, 7, 'ver', 4))
    intervals.append((7, 8, 'abi', 4))
    intervals.append((8, 9, 'abi_ver', 4))
    intervals.append((9, 16, 'pad', 4))

    if is_64:
        fields = [(16, 2, 'e_type'), (18, 2, 'e_machine'), (20, 4, 'e_version'), (24, 8, 'e_entry'), (32, 8, 'e_phoff'), (40, 8, 'e_shoff'), (48, 4, 'e_flags'), (52, 2, 'e_ehsize'), (54, 2, 'e_phentsize'), (56, 2, 'e_phnum'), (58, 2, 'e_shentsize'), (60, 2, 'e_shnum'), (62, 2, 'e_shstrndx')]
    else:
        fields = [(16, 2, 'e_type'), (18, 2, 'e_machine'), (20, 4, 'e_version'), (24, 4, 'e_entry'), (28, 4, 'e_phoff'), (32, 4, 'e_shoff'), (36, 4, 'e_flags'), (40, 2, 'e_ehsize'), (42, 2, 'e_phentsize'), (44, 2, 'e_phnum'), (46, 2, 'e_shentsize'), (48, 2, 'e_shnum'), (50, 2, 'e_shstrndx')]
    for start, size, cls in fields:
        intervals.append((start, start + size, cls, 4))

    for i, p in enumerate(info['phdrs']):
        start = e['e_phoff'] + i * e['e_phentsize']
        intervals.append((start, start + e['e_phentsize'], f"bin_phdr{i} phdr", 2))
        if is_64:
            p_fields = [(0, 4, 'p_type'), (4, 4, 'p_flags'), (8, 8, 'p_offset'), (16, 8, 'p_vaddr'), (24, 8, 'p_paddr'), (32, 8, 'p_filesz'), (40, 8, 'p_memsz'), (48, 8, 'p_align')]
        else:
            p_fields = [(0, 4, 'p_type'), (4, 4, 'p_offset'), (8, 4, 'p_vaddr'), (12, 4, 'p_paddr'), (16, 4, 'p_filesz'), (20, 4, 'p_memsz'), (24, 4, 'p_flags'), (28, 4, 'p_align')]
        for fs, fz, fc in p_fields:
            intervals.append((start + fs, start + fs + fz, fc, 4))

    for i, s in enumerate(info['shdrs']):
        start = e['e_shoff'] + i * e['e_shentsize']
        intervals.append((start, start + e['e_shentsize'], f"bin_shdr{i} shdr", 2))
        if is_64:
            s_fields = [(0, 4, 'sh_name'), (4, 4, 'sh_type'), (8, 8, 'sh_flags'), (16, 8, 'sh_addr'), (24, 8, 'sh_offset'), (32, 8, 'sh_size'), (40, 4, 'sh_link'), (44, 4, 'sh_info'), (48, 8, 'sh_addralign'), (56, 8, 'sh_entsize')]
        else:
            s_fields = [(0, 4, 'sh_name'), (4, 4, 'sh_type'), (8, 4, 'sh_flags'), (12, 4, 'sh_addr'), (16, 4, 'sh_offset'), (20, 4, 'sh_size'), (24, 4, 'sh_link'), (28, 4, 'sh_info'), (32, 4, 'sh_addralign'), (36, 4, 'sh_entsize')]
        for fs, fz, fc in s_fields:
            intervals.append((start + fs, start + fs + fz, fc, 4))

    for i, p in enumerate(info['phdrs']):
        if p['filesz'] > 0:
            intervals.append((p['offset'], p['offset'] + p['filesz'], f"bin_segment{i} segment", 0, p['filesz'], i))
    for i, s in enumerate(info['shdrs']):
        if s['type'] != 8 and s['size'] > 0:
            intervals.append((s['offset'], s['offset'] + s['size'], f"bin_section{i} section hover", 1))

    # Precalculate spans for each byte
    byte_spans = []
    for i in range(len(data)):
        at_off = []
        for it in intervals:
            if it[0] <= i < it[1]:
                at_off.append(it)
        def sort_key(it):
            prio = it[3]
            size = it[4] if prio == 0 else 0
            idx = it[5] if prio == 0 else 0
            return (prio, -size, idx)
        at_off.sort(key=sort_key)
        res = [it[2] for it in at_off]
        has_segment = any('segment' in r for r in res)
        has_section = any('section' in r for r in res)
        if has_segment and has_section:
            idx = -1
            for j, r in enumerate(res):
                if 'section' in r: idx = j
            res.insert(idx + 1, 'segment_subrange hover')
        byte_spans.append(res)

    out = []
    out.append("<!doctype html>\n<html>\n  <head>\n    <meta charset='utf-8'>\n    <meta name='viewport' content='width=900, initial-scale=1'>\n    <title>" + info['filename'] + "</title>\n")
    out.append("    <style>\n{{STYLE}}\n    </style>\n  </head>\n  <body>\n")
    out.append("    <svg width='100%' height='100%'>\n      <defs>\n        <marker id='arrowhead' viewBox='0 0 10 10' refX='10' refY='5' markerWidth='10' markerHeight='10' orient='auto'>\n          <path d='M 0 0 L 10 5 L 0 10 z' />\n        </marker>\n      </defs>\n      <g id='arrows' stroke='black' stroke-width='1' marker-end='url(#arrowhead)'></g>\n    </svg>\n")
    out.append("    <div id='rightmenu'>\n      <a id='credits' href='https://github.com/rbakbashev/elfcat'>generated with elfcat 0.1.10</a>\n      <button class='textbutton' id='settings_toggle'>Settings</button>\n      <button class='textbutton' id='help_toggle'>Help</button>\n      <div class='right_hidden' id='settings'>\n        <label for='arrow_opacity_range'>Arrow opacity:</label>\n        <input type='range' id='arrow_opacity_range' min='0' max='100' value='100'>\n      </div>\n")
    out.append("      <div class='right_hidden' id='help'>\n        <p>The leftmost column shows offsets within the file. The middle column is the file dump. It has ELF structs, sections and segments highlighted. Some fields that reference areas in the file are clickable and connected with arrows. The rightmost column shows printable ASCII characters corresponding to the file bytes.</p>\n        <p>Legend</p>\n        <ul>\n          <li><span class='legend_rect ident'></span>ELF Identification</li>\n          <li><span class='legend_rect ehdr'></span>ELF Header</li>\n          <li><span class='legend_rect phdr'></span>Program Header</li>\n          <li><span class='legend_rect shdr'></span>Section Header</li>\n          <li><span class='legend_rect segment'></span>Segment</li>\n          <li><span class='legend_rect section'></span>Section</li>\n          <li><span class='legend_rect segm_sect_legend'></span>Segment &amp; Section overlap</li>\n        </ul>\n      </div>\n    </div>\n")
    out.append("    <table>\n")
    out.append(f"      <tr class='fileinfo_file_name'> <td>File name:</td> <td>{info['filename']}</td> </tr>\n")
    out.append(f"      <tr class='fileinfo_file_size'> <td>File size:</td> <td>{format_size(info['file_size'])}</td> </tr>\n")
    out.append(f"      <tr class='fileinfo_class'> <td>Object class:</td> <td>{'64-bit' if is_64 else '32-bit'}</td> </tr>\n")
    out.append(f"      <tr class='fileinfo_data'> <td>Data encoding:</td> <td>{'Little endian' if info['is_le'] else 'Big endian'}</td> </tr>\n")
    out.append(f"      <tr class='fileinfo_abi'> <td>ABI:</td> <td>{get_abi_str(data[7])}</td> </tr>\n")
    out.append(f"      <tr class='fileinfo_e_type'> <td>Type:</td> <td>{get_type_str(e['e_type'])}</td> </tr>\n")
    out.append(f"      <tr class='fileinfo_e_machine'> <td>Architecture:</td> <td>{get_machine_str(e['e_machine'])}</td> </tr>\n")
    out.append(f"      <tr class='fileinfo_e_entry'> <td>Entrypoint:</td> <td><span class='number' title='{e['e_entry']}'>{hex(e['e_entry'])}</span></td> </tr>\n")
    out.append(f"      <tr class='fileinfo_ph'> <td>Program headers:</td> <td><span title='{hex(e['e_phnum'])}' class='number fileinfo_e_phnum'>{e['e_phnum']}</span> * <span title='{hex(e['e_phentsize'])}' class='number fileinfo_e_phentsize'>{e['e_phentsize']}</span> @ <span title='{hex(e['e_phoff'])}' class='number fileinfo_e_phoff'>{e['e_phoff']}</span></td> </tr>\n")
    out.append(f"      <tr class='fileinfo_sh'> <td>Section headers:</td> <td><span title='{hex(e['e_shnum'])}' class='number fileinfo_e_shnum'>{e['e_shnum']}</span> * <span title='{hex(e['e_shentsize'])}' class='number fileinfo_e_shentsize'>{e['e_shentsize']}</span> @ <span title='{hex(e['e_shoff'])}' class='number fileinfo_e_shoff'>{e['e_shoff']}</span></td> </tr>\n")
    out.append("    </table>\n")

    offsets_out = []
    bytes_out = []
    ascii_out = []
    current_spans = []
    for i in range(len(data)):
        if i % 16 == 0: offsets_out.append(f"{hex(i)[2:]}\n")
        spans = byte_spans[i]
        while len(current_spans) > 0 and (len(spans) < len(current_spans) or spans[:len(current_spans)] != current_spans):
            bytes_out.append("</span>")
            current_spans.pop()
        while len(current_spans) < len(spans):
            cls = spans[len(current_spans)]
            bytes_out.append(f"<span class='{cls}'>")
            current_spans.append(cls)
        if i < 4 and 'magic' in current_spans:
            if i == 0: bytes_out.append("7f")
            elif i == 1: bytes_out.append("&nbsp;E")
            elif i == 2: bytes_out.append("&nbsp;L")
            elif i == 3: bytes_out.append("&nbsp;F")
        else:
            bytes_out.append(f"{data[i]:02x}")
        if i % 16 == 15 or i == len(data) - 1: bytes_out.append("\n")
        else: bytes_out.append(" ")
        c = data[i]
        ascii_out.append(html.escape(chr(c)) if 0x20 <= c <= 0x7e else ".")
        if i % 16 == 15 or i == len(data) - 1: ascii_out.append("\n")
    while len(current_spans) > 0:
        bytes_out.append("</span>")
        current_spans.pop()

    out.append(f"    <div id='offsets'>{''.join(offsets_out)}</div>\n")
    out.append(f"    <div id='bytes'>{''.join(bytes_out)}</div>\n")
    out.append(f"    <div id='ascii'>{''.join(ascii_out)}</div>\n")
    out.append("    <table id='sticky_table' cellspacing='0'>\n      <tr>\n        <td id='desc'></td>\n        <td class='infotables'>\n")
    for p in info['phdrs']:
        out.append(f"          <table class='conceal itable' id='info_phdr{p['index']}'>\n          <th colspan='2' class='phdr_itable'></th>\n            <tr> <td>Type:</td> <td>{get_phdr_type(p['type'])}</td> </tr>\n            <tr> <td>Flags:</td> <td>{p_flags_str(p['flags'])}</td> </tr>\n            <tr> <td>Offset in file:</td> <td><span class='number' title='{p['offset']}'>{hex(p['offset'])}</span></td> </tr>\n            <tr> <td>Size in file:</td> <td><span class='number' title='{hex(p['filesz'])}'>{p['filesz'] if p['filesz'] < 1024 else format_size(p['filesz']).split(' (')[0] + ' (' + str(p['filesz']) + ')'}</span></td> </tr>\n            <tr> <td>Vaddr in memory:</td> <td><span class='number' title='{p['vaddr']}'>{hex(p['vaddr'])}</span></td> </tr>\n            <tr> <td>Size in memory:</td> <td><span class='number' title='{hex(p['memsz'])}'>{p['memsz'] if p['memsz'] < 1024 else format_size(p['memsz']).split(' (')[0] + ' (' + str(p['memsz']) + ')'}</span></td> </tr>\n            <tr> <td>Alignment:</td> <td><span class='number' title='{p['align']}'>{hex(p['align'])}</span></td> </tr>\n          </table>\n")
    for s in info['shdrs']:
        out.append(f"          <table class='conceal itable' id='info_shdr{s['index']}'>\n          <th colspan='2' class='shdr_itable'></th>\n            <tr> <td>Index:</td> <td>{s['index']}</td> </tr>\n            <tr> <td>Name:</td> <td>{s['name']}</td> </tr>\n            <tr> <td>Type:</td> <td>{get_shdr_type(s['type'])}</td> </tr>\n            <tr> <td>Flags:</td> <td>{sh_flags_str(s['flags'])}</td> </tr>\n            <tr> <td>Vaddr in memory:</td> <td><span class='number' title='{s['addr']}'>{hex(s['addr'])}</span></td> </tr>\n            <tr> <td>Offset in file:</td> <td><span class='number' title='{s['offset']}'>{hex(s['offset'])}</span></td> </tr>\n            <tr> <td>Size in file:</td> <td><span class='number' title='{hex(s['size'])}'>{s['size']}</span></td> </tr>\n            <tr> <td>Linked section:</td> <td>{s['link']}</td> </tr>\n            <tr> <td>Extra info:</td> <td><span class='number' title='{hex(s['info'])}'>{s['info']}</span></td> </tr>\n            <tr> <td>Alignment:</td> <td><span class='number' title='{s['addralign']}'>{hex(s['addralign'])}</span></td> </tr>\n            <tr> <td>Size of entries:</td> <td><span class='number' title='{hex(s['entsize'])}'>{s['entsize']}</span></td> </tr>\n          </table>\n")
    out.append("        </td>\n      </tr>\n    </table>\n")
    out.append("{{SCRIPTS}}\n")
    out.append("    <script type='text/javascript'>\n")
    out.append(f"      connect('.e_phoff', '.bin_phdr0');\n")
    out.append(f"      connect('.e_shoff', '.bin_shdr0');\n")
    for p in info['phdrs']:
        if p['filesz'] > 0: out.append(f"      connect('.bin_phdr{p['index']} > .p_offset', '.bin_segment{p['index']}');\n")
    for s in info['shdrs']:
        if s['type'] != 8 and s['size'] > 0: out.append(f"      connect('.bin_shdr{s['index']} > .sh_offset', '.bin_section{s['index']}');\n")
        if s['link'] != 0: out.append(f"      connect('.bin_shdr{s['index']} > .sh_link', '.bin_shdr{s['link']}');\n")
    out.append("    </script>\n  </body>\n</html>\n")
    with open(info['filename'] + ".html", 'w') as f: f.write("".join(out))

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: elfcat <filename>")
        sys.exit(1)
    info = get_elf_info(sys.argv[1])
    if info: generate_html(info)
EOF
"}

